# RWDM_STRETCH: Stretch: scale a region in one direction between two points. The script rwdm_stretch_script.txt is generated by rwdm_gen.py (the closed forms are in that file); every case moves each Point object
# from its closed-form image E_k to the origin and lists it: the app prints a coordinate within 1e-9 of an integer as that integer, so a
# passing case means every image lies within 1e-9 of the textbook formula (a residual of 1e-6 would read 1e-06; RWDM_*_sensitivity checks that).
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RWDM_STRETCH_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rwdm_stretch_script.txt" 2>&1)" || { echo "$RWDM_STRETCH_OUT" | tail -40; echo "FAIL RWDM_STRETCH_run: script exited non-zero"; fail=1; RWDM_STRETCH_OUT=""; }
else
  RWDM_STRETCH_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rwdm_stretch_script.txt" 2>&1)" || { echo "$RWDM_STRETCH_OUT" | tail -40; echo "FAIL RWDM_STRETCH_run: script exited non-zero"; fail=1; RWDM_STRETCH_OUT=""; }
fi
rwdm_stretch_block() { awk -v name="$1" '$0 ~ ("Unknown command: RWDMBEGIN_" name "$") { on = 1; next } on && /Unknown command: RWDMBEGIN_/ { exit } on { print }' <<<"$RWDM_STRETCH_OUT"; }
# rwdm_stretch_check NAME N DESC: the case listed exactly N points and every one of them is "0,0,0" (the residual to the closed form)
rwdm_stretch_check() {
  local blk npts zeros; blk="$(rwdm_stretch_block "$1")"
  npts="$({ grep -cE '^history: Object [0-9]+ \(point\)' <<<"$blk" || true; })"
  zeros="$({ grep -cE '^history:   0,0,0$' <<<"$blk" || true; })"
  if [ "$npts" = "$2" ] && [ "$zeros" = "$2" ]; then echo "ok   RWDM_STRETCH_$1: $3 ($2 points, every one within 1e-9 of the closed form)"
  else echo "FAIL RWDM_STRETCH_$1: $3 (listed $npts points, $zeros at residual 0; expected $2 and $2)"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -12 | sed 's/^/     residual: /'; fi
}
rwdm_stretch_check zaxis 6 "Stretch the region of the axis (0,0,0)->(0,0,4) to length 6: below the start nothing moves, inside z scales by 6/4, beyond the end the rest shifts by 2"
# negative control: the same harness must SEE a 1e-6 error (point moved 1e-6 off its expected image reads 1e-06, not 0)
rwdm_stretch_sens() {
  local blk; blk="$(rwdm_stretch_block sensitivity)"
  if grep -qE '^history:   (0,0,)?[-0-9.e]*1e-06' <<<"$blk" && ! grep -qE '^history:   0,0,0$' <<<"$blk"; then echo "ok   RWDM_STRETCH_sensitivity: the residual harness reports a 1e-6 error as 1e-06 (negative control)"
  else echo "FAIL RWDM_STRETCH_sensitivity: a 1e-6 error was not visible"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -4 | sed 's/^/     residual: /'; fi
}
rwdm_stretch_sens
